# @url https://atcoder.jp/contests/abc477/tasks/abc477_b
# @primary enumeration
# @topics enumeration, array
# @note
# Idea: For every person, scan all other people and check whether any distance is smaller than D. Output the indices for which no such person exists.
# Key observation: A person is valid exactly when every pairwise distance from that person to another person is at least D, so checking all ordered pairs directly is sufficient.
# Complexity: O(N^2) time and O(N) space.
# @endnote
import sys

input = sys.stdin.readline


def solve():
    n, d = map(int, input().strip().split())
    a = list(map(int, input().strip().split()))

    res = []
    for i in range(n):
        t = 0
        for j in range(n):
            if j != i:
                if abs(a[i] - a[j]) < d:
                    t = 1
        if t == 0: res.append(i + 1)

    if len(res) == 0:print(0)
    else:
        print(len(res))
        print(*res, end = ' ')

    pass


if __name__ == "__main__":
    solve()

# @url https://codeforces.com/contest/2008/problem/E
# @primary enumeration
# @topics case-analysis, incremental-construction
# @note
# Idea: For even length, independently choose the most frequent character on odd and even positions. For odd length, enumerate the deleted position while maintaining character frequencies on the left and right.
# Key observation: After deleting one character, the parity of every position to its right is reversed, so the resulting odd-position count combines left odd positions with right even positions, and vice versa.
# Complexity: O(26N) time and O(26) space per test case.
# @endnote


import sys

input = sys.stdin.readline


def solve_case():
    n = int(input())
    s = ' ' + input().strip()
    res = 0

    al = [chr(x) for x in range(ord('a'), ord('z') + 1)]

    if n % 2 == 0:
        od = {}
        ev = {}
        for i in range(1, n + 1):
            if i % 2 == 0: ev[s[i]] = ev.get(s[i], 0) + 1
            else : od[s[i]] = od.get(s[i], 0) + 1

        res = n - max(od.values()) - max(ev.values())
    else:
        res = 1e6 
        od = {}
        ev = {}
        for i in range(1, n + 1):
            if i % 2 == 0: ev[s[i]] = ev.get(s[i], 0) + 1
            else : od[s[i]] = od.get(s[i], 0) + 1
        # od ev分别是,奇数位偶数位最多的字母, 且不删
        lfod = {}
        lfev = {}
        # 这两个是从做往右枚举的
        for i in range(1, n + 1):
            # 枚举删第 i 个, 如果要删，带来的影响是后面奇数位偶数位互换

            # 1. 首先把自己删掉
            if i % 2 == 0: ev[s[i]] = max(0, ev.get(s[i], 0) - 1)
            else :         od[s[i]] = max(0, od.get(s[i], 0) - 1)

            res_od, res_ev = {}, {}
            # 2. 算左边和右边的值, 因为奇偶互换了所以左奇数加右偶数,左偶数加右奇数
            for j in al:
                res_ev[j] = lfev.get(j, 0) + od.get(j, 0)
                res_od[j] = lfod.get(j, 0) + ev.get(j, 0)

            # 3. 计算当前删掉 第 i 个 的答案
            res = min(res, n - max(res_od.values()) - max(res_ev.values()))

            #还原
            # 如果删的是 第 i + 1 个，是需要lfod\lfev存档的左, 没有删除的奇偶性是不改变的
            if i % 2 == 0: lfev[s[i]] = lfev.get(s[i], 0) + 1
            else : lfod[s[i]] = lfod.get(s[i], 0) + 1

        res = max(1, res)

    return res



def main():
    t = int(input())

    for _ in range(t):
        print(solve_case())


if __name__ == "__main__":
    main()

# @url https://codeforces.com/contest/2254/problem/C2
# @primary sorting-greedy
# @topics sorting-greedy, comparison-sorting
# @rating 1200
# @division div3
# @note
# Idea: Record the positions of ones in both strings separately for even and odd indices. If the corresponding counts differ, output -1; otherwise sort each position list, pair positions in order, and sum half of their absolute distances.
# Key observation: A one can move only between positions of the same parity, and each operation shifts it by two positions. Pairing the sorted positions in the same order minimizes the total movement within each parity class.
# Complexity: O(N log N) time and O(N) space per test case.
# @endnote

import sys

input = sys.stdin.readline


def solve_case():
    n = int(input().strip())
    a = input().strip()
    b = input().strip()
    oda = []
    eva = []
    odb = []
    evb = []
    for i in range(n):
        if i % 2 == 0:
            if a[i] == '1': eva.append(i + 1)
            if b[i] == '1': evb.append(i + 1)
        else:
            if a[i] == '1': oda.append(i + 1)
            if b[i] == '1': odb.append(i + 1)

    if len(eva) == len(evb) and len(oda) == len(odb): 
        res = 0
        eva = sorted(eva)
        evb = sorted(evb)
        oda = sorted(oda)
        odb = sorted(odb)
        k = len(eva)
        for i in range(k):
            res += abs(evb[i] - eva[i]) // 2
        k = len(odb)
        for i in range(k):
            res += abs(oda[i] - odb[i]) // 2
        print(res)
    else: print("-1")
    pass


def main():
    t = int(input())

    for _ in range(t):
        solve_case()


if __name__ == "__main__":
    main()

# @url https://codeforces.com/contest/2259/problem/D
# @primary greedy-construction
# @topics greedy-construction, array
# @rating 1200
# @division div3
# @note
# Idea: Count the number of zeros first. If there is exactly one zero, report that no construction exists. Otherwise construct the assignment string directly: with no zeros, cycle through A, B, C; with at least two zeros, place the first two zeros into different groups and assign the remaining elements using the fixed pattern in the code.
# Key observation: The construction only needs special handling for zero values because the MEX of each multiset is determined by whether zero and subsequent required values are present; a single zero cannot be shared across multiple multisets, while zero zeros or at least two zeros allow the code's direct construction.
# Complexity: O(N) time and O(N) space per test case for the input array.
# @endnote

import sys

input = sys.stdin.readline


def solve_case():
    n = int(input().strip())
    a = list(map(int, input().split()))
    if a.count(0) == 1:
        print("NO")
        return
    print("YES")
    if a.count(0) == 0:
        for i in range(n):
            if i % 3 == 0: print("A", end='')
            elif i % 3 == 1: print("B", end='')
            else:print("C", end='')
    else:
        cnt_0 = 0
        for i in range(n):
            if a[i] == 0 and cnt_0 == 0: 
                print("A", end='')
                cnt_0 += 1
            elif a[i] == 0 and cnt_0 == 1: 
                print("B", end='')
                cnt_0 += 1
            elif a[i] == 0: print("A", end='')
            else:print("C", end='')
    print()
    pass


def main():
    t = int(input())

    for _ in range(t):
        solve_case()


if __name__ == "__main__":
    main()

# @url https://codeforces.com/contest/2259/problem/E
# @primary greedy-construction
# @topics greedy-construction, difference-array
# @rating 1500
# @division div3
# @note
# Idea: Use a difference array to mark every position that cannot contain treasure because it lies strictly inside the required distance interval of a known positive value. First force every known zero position to contain treasure, then for each positive a[i], place treasure at one of the two possible endpoints i-a[i] or i+a[i] if neither endpoint has already satisfied the constraint.
# Key observation: For a known positive distance a[i], no treasure may appear strictly closer than a[i], while at least one valid endpoint exactly a[i] away must contain treasure. The difference array lets the code test forbidden positions in O(1) after preprocessing.
# Complexity: O(N) time and O(N) space per test case.
# @endnote

import sys

input = sys.stdin.readline


def solve_case():
    n = int(input().strip())
    a = [0] + list(map(int, input().strip().split()))
    if a.count(-1) == n:
        print(1,end='')
        print("0"*(n-1))
        return

    dif = [0] * (n + 5)

    for i in range(1, n + 1):
        if a[i] != -1 and a[i] > 0:
            l = max(1, i - a[i] + 1)
            r = min(n, i + a[i] - 1)
            if l <= r:
                dif[l] += 1
                dif[r + 1] -= 1

    pre = [0] * (n + 5)
    for i in range(1, n + 1):
        pre[i] = pre[i - 1] + dif[i]

    res = [0] * (n)

    for i in range(1, n + 1):
        if a[i] == 0:
            if pre[i] > 0:
                print("-1")
                return
            res[i - 1] = 1

    for i in range(1, n + 1):
        if a[i] != -1 and a[i] > 0:
            l = i - a[i]
            r = i + a[i]

            if l >= 1 and res[l - 1] == 1:
                continue
            if r <= n and res[r - 1] == 1:
                continue

            if l >= 1 and pre[l] == 0:
                res[l - 1] = 1
            elif r <= n and pre[r] == 0:
                res[r - 1] = 1
            else:
                print("-1")
                return

    for i in res:
        print(i, end='')
    print()
    pass


def main():
    t = int(input())

    for _ in range(t):
        solve_case()


if __name__ == "__main__":
    main()

# @url https://codeforces.com/contest/2267/problem/D
# @primary sorting-greedy
# @topics sorting-greedy, comparison-sorting, hash-map
# @note
# Idea: Separate values by their original index parity and sort both groups. Construct a candidate sequence by repeatedly taking the smallest available value of the required parity that is at least the previous value; after reaching n, rebuild the remaining values in descending order and continue by taking the largest valid value below the previous one.
# Key observation: Values can only be selected from the parity class required by the current position, so the construction greedily chooses the closest feasible value in the required direction while frequency maps prevent reusing elements.
# Complexity: O(N log N) time and O(N) space per test case.
# @endnote

import sys

input = sys.stdin.readline


def solve_case():
    n = int(input())

    a = [0] + list(map(int, input().strip().split()))
    od = {}
    ev = {}
    odl = []
    evl = []
    m = 1
    for i in range(1, n + 1):
        if i % 2 != 0: 
            od[a[i]] = od.get(a[i], 0) + 1
            odl.append(a[i])
        else: 
            if a[i] == n: m = 2
            evl.append(a[i])
            ev[a[i]] = ev.get(a[i], 0) + 1

    flag = 0

    for i in range(1, n):
        if a[i] < a[i - 1]: flag = 1
    if not flag: return "YES"


    odl = sorted(odl)
    evl = sorted(evl)
    resl = [0]
    flag = 0
    # flag == 0 的时候没有找到 n
    k, j = 0, 0
    cnt = 0
    # 找大的，找小的
    len_evl = len(evl)
    len_odl = len(odl)
    for i in range(1, n + 1):
        if flag == 0:
            if i % 2 == 0:
                while k < len_evl and evl[k] < resl[cnt]: k += 1
                if k < len_evl: 
                    resl.append(evl[k])
                    cnt += 1
                    ev[evl[k]] -= 1 #这个数有没有被用过
                    if evl[k] == n: flag = 1

            else:
                while j < len_odl and odl[j] < resl[cnt]: j += 1
                if j < len_odl: 
                    resl.append(odl[j])
                    cnt += 1
                    od[odl[j]] -= 1
                    if odl[j] == n: flag = 1

        else:
            if flag == 1:
                odll = []
                evll = []
                for ttt in ev:
                    if ev[ttt] > 0: evll.append(ttt)
                for ttt in od:
                    if od[ttt] > 0: odll.append(ttt)
                flag += 1
                k, j = 0, 0
                odll = sorted(odll, reverse=True)
                evll = sorted(evll, reverse=True)
                lk = len(evll)
                lj = len(odll)

                if i % 2 == 0:
                    while k < lk and evll[k] > resl[cnt]: k += 1
                    if k < lk: 
                        resl.append(evll[k])
                        cnt += 1
                else:
                    while j < lj and odll[j] > resl[cnt]: j += 1
                    if j < lj: 
                        resl.append(odll[j])
                        cnt += 1
            else:
                if i % 2 == 0:
                    while k < lk and evll[k] > resl[cnt]: k += 1
                    if k < lk: 
                        resl.append(evll[k])
                        cnt += 1
                else:
                    while j < lj and odll[j] > resl[cnt]: j += 1
                    if j < lj: 
                        resl.append(odll[j])
                        cnt += 1

    if len(resl) - 1 == n: return "YES"
    else: return "NO"
    pass


def main():
    t = int(input())

    for _ in range(t):
        print(solve_case())


if __name__ == "__main__":
    main()

# @url https://codeforces.com/contest/2269/problem/B
# @primary functional-graph
# @topics functional-graph, hash-map, simulation
# @division div2
# @note
# Idea: For every starting number, repeatedly replace it by the sum of squares of its digits while storing visited states and their indices until reaching either a fixed point or a cycle. Then compare every pair using their fixed points or their states at a common time inside their eventual cycles.
# Key observation: The digit-square transformation is deterministic, so every starting value eventually enters a fixed point or directed cycle. Two sequences are permanently identical exactly when they reach the same state at the same time and therefore follow the same deterministic suffix forever.
# Complexity: O(NL + N^2) time and O(NL) space per test case, where L is the maximum generated sequence length before repetition.
# @endnote

import sys

input = sys.stdin.readline


def solve_case():
    n = int(input().strip())
    a = [0] + input().strip().split()
    b = [0] * (n + 1)
    def solve(x):

        t = 0
        last = t
        for i in x:
            t += int(i) * int(i)
        k = {}
        p = []
        q = 0
        while t != last and k.get(t, -1) == -1:
            last = t
            k[last] = q
            p.append(last)
            q += 1

            t = 0
            for i in str(last):
                t += int(i) * int(i)


        if t == last: return [True, t]
        else: return [False, q, p, k[t]]

    for i in range(1, n + 1):
        b[i] = solve(a[i])

    res = 0
    for i in range(1, n):
        if b[i][0] == True:
            for j in range(i + 1, n + 1):
                if b[j][0] == True and b[j][1] == b[i][1]: res += 1
        else:
            for j in range(i + 1, n + 1):
                if b[j][0] == False:
                    l = max(b[i][3], b[j][3])

                    if l < b[i][1]:
                        x = b[i][2][l]
                    else:
                        x = b[i][2][b[i][3] + (l - b[i][3]) % (b[i][1] - b[i][3])]


                    if l < b[j][1]:
                        y = b[j][2][l]
                    else:
                        y = b[j][2][b[j][3] + (l - b[j][3]) % (b[j][1] - b[j][3])]

                    if x == y:
                        res += 1
    print(res)

    pass


def main():
    t = int(input())

    for _ in range(t):
        solve_case()


if __name__ == "__main__":
    main()

# @url https://dmoj.ca/problem/acsl1p4
# @primary depth-first-search
# @topics depth-first-search
# @note
# Idea: Build a directed graph from each match result, directing the edge from the winner to the loser. Start a DFS from every vertex and check whether the search can return to its starting vertex; count every starting vertex for which this is possible.
# Key observation: A vertex belongs to a directed cycle exactly when there exists a directed path starting from that vertex that eventually returns to itself.
# Complexity: O(N(N + K)) time and O(N + K) space.
# @endnote

import sys

input = sys.stdin.readline


def solve():
    n, k = map(int, input().split())

    adj = [[] for _ in range(n)]

    for _ in range(k):
        a, b, sa, sb = map(int, input().split())
        a -= 1
        b -= 1

        if sa > sb:
            adj[a].append(b)
        else:
            adj[b].append(a)

    cycle = set()

    for start in range(n):
        vis = [False] * n
        vis[start] = True

        def dfs(x):
            for y in adj[x]:
                if y == start:
                    return True

                if not vis[y]:
                    vis[y] = True
                    if dfs(y):
                        return True

            return False

        if dfs(start):
            cycle.add(start)

    print(len(cycle))


if __name__ == "__main__":
    solve()

/*
@url https://leetcode.com/problems/car-fleet/
@primary monotonic-stack
@topics comparison-sorting, ordered-map, general-greedy
@note
核心思路：
按照车辆与终点的距离，从最靠近终点的车辆开始向后处理。
每辆车单独到达终点所需时间为 (target - position[i]) / speed[i]。

如果后车的到达时间小于等于前方车队的到达时间，它一定会在终点前
或恰好在终点追上前方车队，因此不会形成新的车队。
只有当前车辆的到达时间严格大于前方最后一个车队的到达时间时，
才会产生一个新的车队。

代码中使用 map 的负位置作为键，使遍历顺序从位置最大到位置最小。
到达时间形成单调序列；由于这里只需要统计车队数量，所以不需要保存
完整的单调栈，只需要保存当前最后一个车队的到达时间 cur。

复杂度：
时间复杂度 O(n log n)，其中排序由 map 完成。
空间复杂度 O(n)。

复习重点：
1. 必须从最靠近终点的车辆向后判断。
2. 相同到达时间属于同一个车队，所以只有 time > cur 时答案才加一。
3. 这道题虽然代码没有显式使用 stack，但本质是 Monotonic Stack 模型。
@endnote
*/

#include <map>
#include <vector>
using namespace std;

class Solution {
public:
    int carFleet(int target, vector<int>& position, vector<int>& speed) {
        map<int, double> cars;

        const int n = static_cast<int>(position.size());
        for (int i = 0; i < n; ++i) {
            cars[-position[i]] =
                static_cast<double>(target - position[i]) / speed[i];
        }

        int fleets = 0;
        double latestArrivalTime = 0.0;

        for (const auto& [negativePosition, arrivalTime] : cars) {
            (void)negativePosition;
            if (arrivalTime > latestArrivalTime) {
                latestArrivalTime = arrivalTime;
                ++fleets;
            }
        }

        return fleets;
    }
};

/*
@url https://leetcode.com/problems/min-stack/
@primary stack
@topics array, implementation
@note
核心思路：
栈中的每个元素同时保存两个值：
1. 当前压入的实际数值。
2. 从栈底到当前位置为止的最小值。

push 时，新位置的最小值等于 min(val, 之前的最小值)。
pop 时，数值和对应的最小值一起删除。
因此 top 和 getMin 都只需要访问最后一个元素，不需要重新遍历整个栈。

状态表示：
st[i][0] 表示第 i 个元素的实际值。
st[i][1] 表示包含第 i 个元素在内的整个栈的最小值。

复杂度：
push、pop、top、getMin 的时间复杂度均为 O(1)。
保存 n 个元素的空间复杂度为 O(n)。

复习重点：
把需要快速查询的历史状态与每个栈元素一起保存。
这是典型的“辅助状态随主状态同步入栈和出栈”模型。
@endnote
*/

#include <algorithm>
#include <array>
#include <vector>
using namespace std;

class MinStack {
private:
    vector<array<int, 2>> st;

public:
    MinStack() = default;

    void push(int val) {
        const int minimum = st.empty() ? val : min(val, st.back()[1]);
        st.push_back({val, minimum});
    }

    void pop() {
        st.pop_back();
    }

    int top() {
        return st.back()[0];
    }

    int getMin() {
        return st.back()[1];
    }
};
